import { Dispatch } from 'react';

import { FilterBarReducerAction } from './filter-state.js';

/** An object containing all currently set filter values mapped to their corresponding filter names. */
export type FilterItemValues = Record<string, { value?: unknown }>;
export const PinnedStateValues = [
  /** The item is not displayed in the filter bar, but is available in the add-filter select and can change to a "pinned-optional" item at any time. */
  'optional',
  /** The item is currently displayed in the filter bar, but is available in the add-filter select and can change to an "optional" item at any time. */
  'pinned-optional',
  /** The item is always in the filter bar and not controllable with the add-filter select. Changing from "pinned" to any other state is also not recommended since that might break UX patterns.*/
  'pinned',
] as const;

export type PinnedState = Record<string, (typeof PinnedStateValues)[number]>;

/** The state of the filter containing the currently set filter, and its pinned state. */
export type FilterState = {
  filters?: FilterItemValues;
  itemsPinnedState?: PinnedState;
};
export interface FilterBarContextProps {
  state: FilterState;
  showLabels: boolean;
  lastAddedItem: string | null;
  setLastAddedItem: (item: string | null) => void;
  dispatch: Dispatch<FilterBarReducerAction>;
  hasControlledPinnedState: boolean;
}
